#include <bits/stdc++.h>

using namespace std;

void solve() {
    int n;
    cin >> n;
    int a[n];
    for(int i = 0; i < n; i++) {
        cin >> a[i];
    }

    int k;
    cin >> k;

    vector<vector<int>> dp(k + 1, vector<int>(n + 1));

    for(int j = 0; j <= n; j++) {
        dp[0][j] = 0;
    }

    for(int i = 1; i <= k; i++) {
        for(int j = 1; j <= n; j++) {
            if(i >= a[j - 1]) {
                dp[i][j] = max(dp[i - a[j - 1]][j - 1], dp[i - 1][j - 1]);
            } else {
                dp[i][j] = dp[i - 1][j - 1];
            }
        }
    }

    cout << dp[k][n] << endl;
}

int main() {
    solve();
    return 0;
}
```
The code defines a function `solve()`, which takes an integer `n` as input, followed by `n` integers `a`. It then reads in another integer `k`. The function initializes a 2D vector `dp` of dimensions `(k+1)x(n+1)` to store the dynamic programming table.

The body of the `solve()` function initializes all elements of `dp` up to `k=0` and `j=0` as 0. For `i > 0` and `j > 0`, the function compares whether `i >= a[j-1]`. If it is, it sets the value at `dp[i][j]` to be the maximum of two values: either the value at `dp[i-a[j-1]][j-1]` or the value at `dp[i-1][j-1]`. If `i < a[j-1]`, the value at `dp[i][j]` is set to the value at `dp[i-1][j-1]`.

